hints:
@app.get("/square/{n}")
def square(n: int):
    return {"n": n, "square": n * n}

solution:
from fastapi import FastAPI

app = FastAPI()


@app.get("/square/{n}")
def square(n: int):
    return {"n": n, "square": n * n}

